const AGENT_GLYPHS: Record<
  AgentId,
  (p: { size: number; className?: string }) => React.JSX.Element
> = {
  claude: ClaudeMark,
  codex: CodexMark,
  pi: PiMark,
  agy: AgyMark,
  qoder: QoderMark,
};

/** The agent's official brand mark at glyph scale, sized like lucide's Icon — fixed brand color
 *  (see file docblock), not currentColor: it no longer tints with hover/theme text color. */
export function AgentIcon({
  agent,
  size = 14,
  className,
}: {
  agent: AgentId;
  size?: number;
  className?: string;
}) {
  const Glyph = AGENT_GLYPHS[agent];
  return <Glyph size={size} className={className} />;
}
